/// A general category as `Character.getType` returns it, with Java's
/// numbering as the discriminant (17 is unused in Java).
#[derive(Copy, Clone, Debug, Default, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum GeneralCategory {
    /// `Cn`: not assigned to a character (Java `UNASSIGNED`).
    #[default]
    Unassigned = 0,
    /// `Lu`: upper case letter (Java `UPPERCASE_LETTER`).
    UppercaseLetter = 1,
    /// `Ll`: lower case letter (Java `LOWERCASE_LETTER`).
    LowercaseLetter = 2,
    /// `Lt`: title case letter (Java `TITLECASE_LETTER`).
    TitlecaseLetter = 3,
    /// `Lm`: modifier letter (Java `MODIFIER_LETTER`).
    ModifierLetter = 4,
    /// `Lo`: other letter (Java `OTHER_LETTER`).
    OtherLetter = 5,
    /// `Mn`: non-spacing mark (Java `NON_SPACING_MARK`).
    NonSpacingMark = 6,
    /// `Me`: enclosing mark (Java `ENCLOSING_MARK`).
    EnclosingMark = 7,
    /// `Mc`: spacing mark (Java `COMBINING_SPACING_MARK`).
    CombiningSpacingMark = 8,
    /// `Nd`: decimal digit (Java `DECIMAL_DIGIT_NUMBER`).
    DecimalDigitNumber = 9,
    /// `Nl`: letter number (Java `LETTER_NUMBER`).
    LetterNumber = 10,
    /// `No`: other number (Java `OTHER_NUMBER`).
    OtherNumber = 11,
    /// `Zs`: space separator (Java `SPACE_SEPARATOR`).
    SpaceSeparator = 12,
    /// `Zl`: line separator (Java `LINE_SEPARATOR`).
    LineSeparator = 13,
    /// `Zp`: paragraph separator (Java `PARAGRAPH_SEPARATOR`).
    ParagraphSeparator = 14,
    /// `Cc`: control character (Java `CONTROL`).
    Control = 15,
    /// `Cf`: format character (Java `FORMAT`).
    Format = 16,
    /// `Co`: private use (Java `PRIVATE_USE`).
    PrivateUse = 18,
    /// `Cs`: surrogate code unit (Java `SURROGATE`).
    Surrogate = 19,
    /// `Pd`: dash punctuation (Java `DASH_PUNCTUATION`).
    DashPunctuation = 20,
    /// `Ps`: opening punctuation (Java `START_PUNCTUATION`).
    StartPunctuation = 21,
    /// `Pe`: closing punctuation (Java `END_PUNCTUATION`).
    EndPunctuation = 22,
    /// `Pc`: connector punctuation (Java `CONNECTOR_PUNCTUATION`).
    ConnectorPunctuation = 23,
    /// `Po`: other punctuation (Java `OTHER_PUNCTUATION`).
    OtherPunctuation = 24,
    /// `Sm`: mathematical symbol (Java `MATH_SYMBOL`).
    MathSymbol = 25,
    /// `Sc`: currency symbol (Java `CURRENCY_SYMBOL`).
    CurrencySymbol = 26,
    /// `Sk`: modifier symbol (Java `MODIFIER_SYMBOL`).
    ModifierSymbol = 27,
    /// `So`: other symbol (Java `OTHER_SYMBOL`).
    OtherSymbol = 28,
    /// `Pi`: initial quotation mark (Java `INITIAL_QUOTE_PUNCTUATION`).
    InitialQuotePunctuation = 29,
    /// `Pf`: final quotation mark (Java `FINAL_QUOTE_PUNCTUATION`).
    FinalQuotePunctuation = 30,
}

