/// The script of a code point, for the scripts the UAX #29 word type
/// distinguishes (Java's `Character.UnicodeScript` for these).
#[derive(Copy, Clone, Debug, Default, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum Script {
    /// Any other script, `Common`, `Inherited` and `Unknown` included.
    #[default]
    Other = 0,
    /// Han ideographs.
    Han = 1,
    /// Hiragana.
    Hiragana = 2,
    /// Katakana.
    Katakana = 3,
    /// Hangul.
    Hangul = 4,
    /// Thai.
    Thai = 5,
    /// Lao.
    Lao = 6,
    /// Myanmar.
    Myanmar = 7,
    /// Khmer.
    Khmer = 8,
    /// Tai Le.
    TaiLe = 9,
    /// New Tai Lue.
    NewTaiLue = 10,
    /// Tai Viet.
    TaiViet = 11,
}

impl Script {
    /// Every value, in discriminant order.
    pub const ALL: [Script; 12] = [
        Script::Other,
        Script::Han,
        Script::Hiragana,
        Script::Katakana,
        Script::Hangul,
        Script::Thai,
        Script::Lao,
        Script::Myanmar,
        Script::Khmer,
        Script::TaiLe,
        Script::NewTaiLue,
        Script::TaiViet,
    ];

    /// The `Character.UnicodeScript` constant name, such as `TAI_LE`; `OTHER` for `Other`.
    pub const fn java_name(self) -> &'static str {
        match self {
            Script::Other => "OTHER",
            Script::Han => "HAN",
            Script::Hiragana => "HIRAGANA",
            Script::Katakana => "KATAKANA",
            Script::Hangul => "HANGUL",
            Script::Thai => "THAI",
            Script::Lao => "LAO",
            Script::Myanmar => "MYANMAR",
            Script::Khmer => "KHMER",
            Script::TaiLe => "TAI_LE",
            Script::NewTaiLue => "NEW_TAI_LUE",
            Script::TaiViet => "TAI_VIET",
        }
    }

    /// The script with this `Scripts.txt` value name, such as `Tai_Le`.
    pub fn from_property_name(label: &str) -> Option<Script> {
        match label {
            "Other" => Some(Script::Other),
            "Han" => Some(Script::Han),
            "Hiragana" => Some(Script::Hiragana),
            "Katakana" => Some(Script::Katakana),
            "Hangul" => Some(Script::Hangul),
            "Thai" => Some(Script::Thai),
            "Lao" => Some(Script::Lao),
            "Myanmar" => Some(Script::Myanmar),
            "Khmer" => Some(Script::Khmer),
            "Tai_Le" => Some(Script::TaiLe),
            "New_Tai_Lue" => Some(Script::NewTaiLue),
            "Tai_Viet" => Some(Script::TaiViet),
            _ => None,
        }
    }
}

/// The bits of the flag table, one byte per code point.
pub(crate) mod flag {
    /// `Character.isWhitespace(int)`.
    pub const WHITESPACE: u8 = 0x01;
    /// `Character.isAlphabetic(int)`.
    pub const ALPHABETIC: u8 = 0x02;
    /// `Character.isUpperCase(int)`.
    pub const UPPER_CASE: u8 = 0x04;
    /// `Character.isLetter(int)`.
    pub const LETTER: u8 = 0x08;
    /// `Character.isDigit(int)`.
    pub const DIGIT: u8 = 0x10;
    /// `Character.toLowerCase(int)` returns a different code point.
    pub const HAS_LOWER_CASE: u8 = 0x20;
}

/// The general category of a code point.
#[inline]
pub(crate) fn general_category(cp: u32) -> GeneralCategory {
    crate::trie::lookup(&category::INDEX, &category::BLOCKS, cp)
}

/// The flag byte of a code point; see [`flag`].
#[inline]
pub(crate) fn flags(cp: u32) -> u8 {
    crate::trie::lookup(&flag_table::INDEX, &flag_table::BLOCKS, cp)
}

/// The script of a code point, as far as [`Script`] distinguishes them.
#[inline]
pub(crate) fn script(cp: u32) -> Script {
    crate::trie::lookup(&script_table::INDEX, &script_table::BLOCKS, cp)
}

/// The simple lowercase mapping: a direct table below U+0800; above
/// it the flag table says whether the code point changes at all, and only
/// those that do are looked up in the sorted pairs.
#[inline]
pub(crate) fn to_lower_case(cp: u32) -> u32 {
    if cp < 0x800 {
        return u32::from(lower::DIRECT[cp as usize]);
    }
    if flags(cp) & flag::HAS_LOWER_CASE == 0 {
        return cp;
    }
    match lower::FROM.binary_search(&cp) {
        Ok(i) => lower::TO[i],
        Err(_) => cp,
    }
}

